use vstd::prelude::*;

fn main() {}

verus!{

// File: defs.rs
pub struct Execution<T> {
    pub nat_to_state: spec_fn(nat) -> T,
}

impl<T> Execution<T> {

    pub open spec fn suffix(self, pos: nat) -> Self {
        Execution {
            nat_to_state: |i: nat| (self.nat_to_state)(i + pos),
        }
    }

}


#[verifier(reject_recursive_types(T))]
pub struct TempPred<T> {
    pub pred: spec_fn(Execution<T>) -> bool,
}

impl<T> TempPred<T> {

    pub open spec fn new(pred: spec_fn(Execution<T>) -> bool) -> Self {
        TempPred {
            pred: pred,
        }
    }

    pub open spec fn satisfied_by(self, execution: Execution<T>) -> bool {
        (self.pred)(execution)
    }

    pub open spec fn and(self, other: Self) -> Self {
        TempPred::new(|ex: Execution<T>| self.satisfied_by(ex) && other.satisfied_by(ex))
    }

    pub open spec fn implies(self, other: Self) -> Self {
        TempPred::new(|ex: Execution<T>| self.satisfied_by(ex) ==> other.satisfied_by(ex))
    }

    pub open spec fn leads_to(self, other: Self) -> Self {
        always(self.implies(eventually(other)))
    }

    pub open spec fn entails(self, other: Self) -> bool {
        valid(self.implies(other))
    }

}


pub open spec fn always<T>(temp_pred: TempPred<T>) -> TempPred<T> {
    TempPred::new(|ex: Execution<T>| forall |i: nat| #[trigger] temp_pred.satisfied_by(ex.suffix(i)))
}

pub open spec fn eventually<T>(temp_pred: TempPred<T>) -> TempPred<T> {
    TempPred::new(|ex: Execution<T>| exists |i: nat| #[trigger] temp_pred.satisfied_by(ex.suffix(i)))
}

pub open spec fn valid<T>(temp_pred: TempPred<T>) -> bool {
    forall |ex: Execution<T>| temp_pred.satisfied_by(ex)
}


// File: rules.rs
	#[verifier::external_body]
proof fn leads_to_unfold<T>(ex: Execution<T>, p: TempPred<T>, q: TempPred<T>)
    requires p.leads_to(q).satisfied_by(ex),
    ensures forall |i: nat| p.implies(eventually(q)).satisfied_by(#[trigger] ex.suffix(i)),
	{
		unimplemented!()
	}

	#[verifier::external_body]
proof fn implies_apply<T>(ex: Execution<T>, p: TempPred<T>, q: TempPred<T>)
    requires
        p.implies(q).satisfied_by(ex),
        p.satisfied_by(ex),
    ensures q.satisfied_by(ex),
	{
		unimplemented!()
	}

	#[verifier::external_body]
proof fn always_propagate_forwards<T>(ex: Execution<T>, p: TempPred<T>, i: nat)
    requires always(p).satisfied_by(ex),
    ensures always(p).satisfied_by(ex.suffix(i)),
	{
		unimplemented!()
	}

pub proof fn pack_conditions_to_spec<T>(spec: TempPred<T>, c: TempPred<T>, p: TempPred<T>, q: TempPred<T>)
    requires spec.entails(p.and(c).leads_to(q)),
    ensures spec.and(always(c)).entails(p.leads_to(q)),
{
    assert forall |ex: Execution<T>| spec.and(always(c)).implies(p.leads_to(q)).satisfied_by(ex) by {
        if spec.and(always(c)).satisfied_by(ex) {
            // Unpack: spec is satisfied and always(c) is satisfied
            assert(spec.satisfied_by(ex));
            assert(always(c).satisfied_by(ex));

            // From entails: spec.implies(p.and(c).leads_to(q)) is valid
            // so it holds for ex
            assert(spec.implies(p.and(c).leads_to(q)).satisfied_by(ex));

            // Apply implication to get p.and(c).leads_to(q) holds on ex
            implies_apply(ex, spec, p.and(c).leads_to(q));
            assert(p.and(c).leads_to(q).satisfied_by(ex));

            // Unfold leads_to: for all i, (p.and(c)).implies(eventually(q)) holds at ex.suffix(i)
            leads_to_unfold(ex, p.and(c), q);

            // Show p.leads_to(q).satisfied_by(ex)
            // = always(p.implies(eventually(q))).satisfied_by(ex)
            // = forall i, p.implies(eventually(q)).satisfied_by(ex.suffix(i))
            assert forall |i: nat| p.implies(eventually(q)).satisfied_by(#[trigger] ex.suffix(i)) by {
                // From always(c).satisfied_by(ex): c holds at every suffix, including ex.suffix(i)
                assert(c.satisfied_by(ex.suffix(i)));

                if p.satisfied_by(ex.suffix(i)) {
                    // Both p and c hold at ex.suffix(i), so p.and(c) holds
                    assert(p.and(c).satisfied_by(ex.suffix(i)));
                    // (p.and(c)).implies(eventually(q)) holds at ex.suffix(i) from leads_to_unfold
                    assert(p.and(c).implies(eventually(q)).satisfied_by(ex.suffix(i)));
                    // Apply implication to get eventually(q) holds at ex.suffix(i)
                    implies_apply(ex.suffix(i), p.and(c), eventually(q));
                    assert(eventually(q).satisfied_by(ex.suffix(i)));
                }
            };
            // Now we have: forall i, p.implies(eventually(q)).satisfied_by(ex.suffix(i))
            // = always(p.implies(eventually(q))).satisfied_by(ex)
            // = p.leads_to(q).satisfied_by(ex)
            assert(p.leads_to(q).satisfied_by(ex));
        }
    };
}


}
